-- Declared foreign keys for communication module, added where the database lacks them
-- Generated by metaphor-schema

DO $$
BEGIN
    IF to_regclass('communication.messages') IS NOT NULL AND to_regclass('communication.threads') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('communication.messages') AND c.contype = 'f' AND a.attname = 'thread_id'
    ) THEN
        ALTER TABLE communication.messages ADD CONSTRAINT fk_messages_thread_id FOREIGN KEY (thread_id) REFERENCES communication.threads (id) NOT VALID;
        BEGIN
            ALTER TABLE communication.messages VALIDATE CONSTRAINT fk_messages_thread_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_messages_thread_id left NOT VALID: stored rows of communication.messages reference missing rows';
        END;
    END IF;
END $$;

